// Visual Direction Engine: pure, serializable domain helpers. This module is
// deliberately independent of DOM, Electron, providers, and project storage so
// both the UI and generation layers can resolve the same Style DNA safely.

export const VISUAL_DIRECTION_SCHEMA_VERSION = 1;
export const STYLE_REFERENCE_ROLES = ["overall", "character", "environment", "palette", "lighting", "composition", "materials", "camera", "texture", "motion"];
export const STYLE_STRENGTHS = { subtle: 0.3, balanced: 0.55, strong: 0.78, signature: 1 };

const now = () => new Date().toISOString();
const idPart = () => `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
const array = (value) => Array.isArray(value) ? value.filter(Boolean).map(String) : [];
const text = (value, fallback = "") => typeof value === "string" ? value.trim() : fallback;
const number = (value, fallback = 50) => Number.isFinite(Number(value)) ? Math.max(0, Math.min(100, Number(value))) : fallback;

export const defaultStyleDna = (input = {}) => {
  const createdAt = text(input.createdAt, now());
  const name = text(input.name, "Untitled Style");
  return {
    id: text(input.id, `style-${idPart()}`),
    schemaVersion: VISUAL_DIRECTION_SCHEMA_VERSION,
    name,
    // Separate from `name`: the text every "STYLE DNA — {x}." prompt prefix
    // actually sends to a model. Identical to `name` for every ordinary
    // style. Director-inspired presets diverge on purpose — `name` carries
    // the director's real name for human browsing, `promptLabel` carries
    // craft-only language so the name itself never reaches generation.
    promptLabel: text(input.promptLabel, name),
    slug: text(input.slug, name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || `style-${idPart()}`),
    description: text(input.description),
    shortDescription: text(input.shortDescription),
    source: ["system", "user", "generated", "imported", "remixed"].includes(input.source) ? input.source : "user",
    categoryIds: array(input.categoryIds),
    tags: array(input.tags),
    thumbnailAssetId: text(input.thumbnailAssetId),
    // Deterministic two-color card treatment used only when no bundled or
    // generated thumbnail exists yet — v1 for presets that don't have
    // bespoke preview art (see directorStyleDnas()).
    cardGradient: Array.isArray(input.cardGradient) && input.cardGradient.length === 2 ? input.cardGradient.map(String) : null,
    previewAssetIds: array(input.previewAssetIds),
    referenceAssets: Array.isArray(input.referenceAssets) ? input.referenceAssets.filter((reference) => reference?.assetId).map((reference) => ({
      assetId: String(reference.assetId), role: STYLE_REFERENCE_ROLES.includes(reference.role) ? reference.role : "overall",
      strength: Math.max(0, Math.min(100, Number(reference.strength) || 50)),
      extract: text(reference.extract), ignore: text(reference.ignore)
    })) : [],
    status: ["draft", "generating", "ready", "failed", "archived"].includes(input.status) ? input.status : "ready",
    visibility: ["private", "project", "shared", "public"].includes(input.visibility) ? input.visibility : "project",
    creativeIntent: {
      summary: text(input.creativeIntent?.summary, text(input.description)),
      emotionalTone: array(input.creativeIntent?.emotionalTone),
      narrativeUseCases: array(input.creativeIntent?.narrativeUseCases),
      audience: array(input.creativeIntent?.audience)
    },
    medium: { primary: text(input.medium?.primary, "digital cinematic"), secondary: array(input.medium?.secondary), handcrafted: Boolean(input.medium?.handcrafted), practical: Boolean(input.medium?.practical), digital: input.medium?.digital !== false },
    visualLanguage: {
      shapeLanguage: text(input.visualLanguage?.shapeLanguage), lineQuality: text(input.visualLanguage?.lineQuality), silhouetteApproach: text(input.visualLanguage?.silhouetteApproach),
      levelOfRealism: number(input.visualLanguage?.levelOfRealism, 55), levelOfStylization: number(input.visualLanguage?.levelOfStylization, 55), detailDensity: number(input.visualLanguage?.detailDensity, 55), visualComplexity: number(input.visualLanguage?.visualComplexity, 55), negativeSpace: number(input.visualLanguage?.negativeSpace, 45)
    },
    materials: { primaryMaterials: array(input.materials?.primaryMaterials), secondaryMaterials: array(input.materials?.secondaryMaterials), surfaceProperties: array(input.materials?.surfaceProperties), imperfections: array(input.materials?.imperfections) },
    color: { paletteName: text(input.color?.paletteName), primaryColors: array(input.color?.primaryColors), secondaryColors: array(input.color?.secondaryColors), accentColors: array(input.color?.accentColors), backgroundColors: array(input.color?.backgroundColors), saturation: number(input.color?.saturation, 55), contrast: number(input.color?.contrast, 55), temperature: ["warm", "cool", "neutral", "mixed"].includes(input.color?.temperature) ? input.color.temperature : "mixed", harmony: text(input.color?.harmony), restrictions: array(input.color?.restrictions) },
    lighting: { approach: text(input.lighting?.approach), keyDirection: text(input.lighting?.keyDirection), softness: number(input.lighting?.softness, 55), contrast: number(input.lighting?.contrast, 55), atmosphere: array(input.lighting?.atmosphere), shadowBehavior: text(input.lighting?.shadowBehavior), practicalLights: array(input.lighting?.practicalLights) },
    composition: { principles: array(input.composition?.principles), framing: array(input.composition?.framing), subjectScale: text(input.composition?.subjectScale), negativeSpaceGuidance: text(input.composition?.negativeSpaceGuidance), depthStrategy: text(input.composition?.depthStrategy), visualHierarchy: text(input.composition?.visualHierarchy) },
    camera: { shotLanguage: array(input.camera?.shotLanguage), lenses: array(input.camera?.lenses), depthOfField: text(input.camera?.depthOfField), cameraHeight: text(input.camera?.cameraHeight), cameraMovement: array(input.camera?.cameraMovement), stabilization: text(input.camera?.stabilization), forbiddenMovements: array(input.camera?.forbiddenMovements) },
    characters: { anatomy: text(input.characters?.anatomy), proportions: text(input.characters?.proportions), facialDesign: text(input.characters?.facialDesign), eyes: text(input.characters?.eyes), hair: text(input.characters?.hair), wardrobe: text(input.characters?.wardrobe), texture: text(input.characters?.texture), actingStyle: text(input.characters?.actingStyle), microAnimation: array(input.characters?.microAnimation), identityConsistencyRules: array(input.characters?.identityConsistencyRules) },
    environments: { architecture: text(input.environments?.architecture), terrain: text(input.environments?.terrain), atmosphericPerspective: text(input.environments?.atmosphericPerspective), worldDensity: text(input.environments?.worldDensity), setDressingRules: array(input.environments?.setDressingRules) },
    props: { designLanguage: text(input.props?.designLanguage), materialRules: array(input.props?.materialRules), scaleRules: array(input.props?.scaleRules) },
    animation: { technique: text(input.animation?.technique), frameFeeling: text(input.animation?.frameFeeling), motionQuality: text(input.animation?.motionQuality), physics: text(input.animation?.physics), secondaryMotion: array(input.animation?.secondaryMotion), transitionRules: array(input.animation?.transitionRules), forbiddenMotion: array(input.animation?.forbiddenMotion) },
    effects: { allowed: array(input.effects?.allowed), restrained: array(input.effects?.restrained), forbidden: array(input.effects?.forbidden) },
    typography: { allowed: Boolean(input.typography?.allowed), approach: text(input.typography?.approach), fontCharacteristics: array(input.typography?.fontCharacteristics), placementRules: array(input.typography?.placementRules) },
    audio: { materialSounds: array(input.audio?.materialSounds), ambience: array(input.audio?.ambience), musicDirection: text(input.audio?.musicDirection), voiceDirection: text(input.audio?.voiceDirection) },
    promptBlocks: { universal: text(input.promptBlocks?.universal), image: text(input.promptBlocks?.image), video: text(input.promptBlocks?.video), negative: text(input.promptBlocks?.negative), character: text(input.promptBlocks?.character), environment: text(input.promptBlocks?.environment), prop: text(input.promptBlocks?.prop), storyboard: text(input.promptBlocks?.storyboard) },
    modelOverrides: input.modelOverrides && typeof input.modelOverrides === "object" ? input.modelOverrides : {},
    continuityRules: array(input.continuityRules), forbiddenElements: array(input.forbiddenElements), lockedProperties: array(input.lockedProperties),
    version: Math.max(1, Number(input.version) || 1), versionId: text(input.versionId, `style-version-${idPart()}`), parentStyleId: text(input.parentStyleId), createdAt, updatedAt: text(input.updatedAt, createdAt), createdBy: text(input.createdBy)
  };
};

export const legacyStyleToDna = (legacy = {}) => defaultStyleDna({
  id: legacy.id || `system-${String(legacy.name || "style").toLowerCase().replace(/[^a-z0-9]+/g, "-")}`,
  name: legacy.name, description: legacy.promptFragment || legacy.description || "", shortDescription: legacy.tone || "", source: "system", visibility: "public", categoryIds: legacy.family ? [legacy.family.toLowerCase().replace(/[^a-z0-9]+/g, "-")] : ["foundation"], tags: [legacy.family, legacy.tone].filter(Boolean),
  creativeIntent: { summary: legacy.promptFragment || "", emotionalTone: legacy.tone ? legacy.tone.split(/[·,]/).map((item) => item.trim()) : [], narrativeUseCases: [] },
  promptBlocks: { universal: legacy.promptFragment || "", image: legacy.promptFragment || "", video: legacy.promptFragment || "", negative: legacy.negativePrompt || "" },
  visualLanguage: { shapeLanguage: legacy.promptFragment || "" }, color: { paletteName: legacy.tone || "" }, lighting: { approach: legacy.promptFragment || "" },
  version: 1, versionId: `system-version-${String(legacy.name || "style").toLowerCase().replace(/[^a-z0-9]+/g, "-")}`
});

